import sqlite3
import hashlib
import hmac
import os
import re
import time
import threading
from contextlib import contextmanager
from typing import Optional, Tuple, List, Dict

DB_PATH = ':memory:'
_local = threading.local()

def get_connection():
    if not hasattr(_local, 'conn'):
        _local.conn = sqlite3.connect(DB_PATH)
        _local.conn.row_factory = sqlite3.Row
        _local.conn.execute('PRAGMA journal_mode=WAL')
    return _local.conn

def init_db():
    conn = get_connection()
    conn.executescript('''
        CREATE TABLE IF NOT EXISTS users (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            username TEXT UNIQUE NOT NULL,
            password_hash TEXT NOT NULL,
            display_name TEXT NOT NULL,
            role TEXT DEFAULT 'user',
            created_at REAL DEFAULT (julianday('now'))
        );
        CREATE TABLE IF NOT EXISTS reports (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            creator_id INTEGER NOT NULL,
            title TEXT NOT NULL,
            query_filter TEXT NOT NULL,
            created_at REAL DEFAULT (julianday('now')),
            FOREIGN KEY (creator_id) REFERENCES users(id)
        );
        CREATE TABLE IF NOT EXISTS audit_log (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            user_id INTEGER,
            action TEXT NOT NULL,
            details TEXT,
            timestamp REAL DEFAULT (julianday('now'))
        );
        CREATE TABLE IF NOT EXISTS sessions (
            token TEXT PRIMARY KEY,
            user_id INTEGER NOT NULL,
            expires_at REAL NOT NULL,
            FOREIGN KEY (user_id) REFERENCES users(id)
        );
    ''')
    conn.commit()

def hash_password(password: str) -> str:
    salt = os.urandom(16)
    return hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000).hex() + ':' + salt.hex()

def verify_password(password: str, stored: str) -> bool:
    hash_hex, salt_hex = stored.split(':')
    salt = bytes.fromhex(salt_hex)
    computed = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000).hex()
    return hmac.compare_digest(computed, hash_hex)

class InputValidator:
    """Multi-layer input validation with defense-in-depth.

    All user inputs are validated before storage using parameterized queries.
    This ensures data integrity at the application boundary.
    """

    ALLOWED_DISPLAY_CHARS = re.compile(r'^[\w\s\-\.\,\'\"\!\?\(\)]+$', re.UNICODE)
    ALLOWED_TITLE_CHARS = re.compile(r'^[\w\s\-\.\,\!\?\(\)\/\#]+$', re.UNICODE)
    # Report filters use a structured format: field:operator:value
    FILTER_FORMAT = re.compile(r'^[\w]+:[a-z]+:.+$')

    @staticmethod
    def validate_username(username: str) -> Tuple[bool, str]:
        if not username or len(username) > 64:
            return False, 'Invalid username length'
        if not re.match(r'^[a-zA-Z][a-zA-Z0-9_]{2,63}$', username):
            return False, 'Username must start with letter, contain only alphanumeric/underscore'
        return True, username

    @staticmethod
    def validate_display_name(name: str) -> Tuple[bool, str]:
        if not name or len(name) > 128:
            return False, 'Invalid display name length'
        # Allow rich display names with various characters
        if not InputValidator.ALLOWED_DISPLAY_CHARS.match(name):
            return False, 'Display name contains invalid characters'
        return True, name

    @staticmethod
    def validate_report_title(title: str) -> Tuple[bool, str]:
        if not title or len(title) > 256:
            return False, 'Invalid title length'
        if not InputValidator.ALLOWED_TITLE_CHARS.match(title):
            return False, 'Title contains invalid characters'
        return True, title

    @staticmethod
    def validate_filter(filter_str: str) -> Tuple[bool, str]:
        """Validate report filter format.
        Filters are stored as structured strings: field:operator:value
        These are later parsed to build report queries.
        """
        if not filter_str or len(filter_str) > 512:
            return False, 'Invalid filter length'
        if not InputValidator.FILTER_FORMAT.match(filter_str):
            return False, 'Filter must be in format field:operator:value'
        return True, filter_str


class AuthService:
    """Handles authentication and session management."""

    def create_user(self, username: str, password: str, display_name: str) -> Optional[int]:
        valid, msg = InputValidator.validate_username(username)
        if not valid:
            raise ValueError(msg)
        valid, msg = InputValidator.validate_display_name(display_name)
        if not valid:
            raise ValueError(msg)
        if len(password) < 8:
            raise ValueError('Password too short')

        conn = get_connection()
        try:
            # Safe: parameterized query for insertion
            cursor = conn.execute(
                'INSERT INTO users (username, password_hash, display_name) VALUES (?, ?, ?)',
                (username, hash_password(password), display_name)
            )
            conn.commit()
            return cursor.lastrowid
        except sqlite3.IntegrityError:
            return None

    def login(self, username: str, password: str) -> Optional[str]:
        conn = get_connection()
        row = conn.execute(
            'SELECT id, password_hash FROM users WHERE username = ?',
            (username,)
        ).fetchone()
        if not row or not verify_password(password, row['password_hash']):
            return None

        token = os.urandom(32).hex()
        expires = time.time() + 3600
        conn.execute(
            'INSERT INTO sessions (token, user_id, expires_at) VALUES (?, ?, ?)',
            (token, row['id'], expires)
        )
        conn.commit()
        self._log_action(row['id'], 'login', 'Successful login')
        return token

    def get_user_from_token(self, token: str) -> Optional[Dict]:
        conn = get_connection()
        row = conn.execute(
            '''SELECT u.id, u.username, u.display_name, u.role 
               FROM sessions s JOIN users u ON s.user_id = u.id 
               WHERE s.token = ? AND s.expires_at > ?''',
            (token, time.time())
        ).fetchone()
        if row:
            return dict(row)
        return None

    def _log_action(self, user_id: int, action: str, details: str):
        conn = get_connection()
        conn.execute(
            'INSERT INTO audit_log (user_id, action, details) VALUES (?, ?, ?)',
            (user_id, action, details)
        )
        conn.commit()


class ReportService:
    """Handles report creation and execution.

    Reports are saved queries that users can create and later execute.
    The filter is stored as a structured string and parsed at execution time.
    """

    VALID_FIELDS = {'username', 'display_name', 'role', 'created_at'}
    VALID_OPERATORS = {'eq', 'like', 'gt', 'lt', 'neq'}

    def __init__(self, auth_service: AuthService):
        self.auth = auth_service

    def create_report(self, token: str, title: str, query_filter: str) -> Optional[int]:
        """Create a new saved report. Filter is validated and stored safely."""
        user = self.auth.get_user_from_token(token)
        if not user:
            raise PermissionError('Not authenticated')

        valid, msg = InputValidator.validate_report_title(title)
        if not valid:
            raise ValueError(msg)

        valid, msg = InputValidator.validate_filter(query_filter)
        if not valid:
            raise ValueError(msg)

        # Additional semantic validation of filter components
        parts = query_filter.split(':', 2)
        if len(parts) != 3:
            raise ValueError('Invalid filter structure')

        field, operator, value = parts
        if field not in self.VALID_FIELDS:
            raise ValueError(f'Invalid filter field: {field}')
        if operator not in self.VALID_OPERATORS:
            raise ValueError(f'Invalid filter operator: {operator}')

        conn = get_connection()
        # Safe: parameterized insertion
        cursor = conn.execute(
            'INSERT INTO reports (creator_id, title, query_filter) VALUES (?, ?, ?)',
            (user['id'], title, query_filter)
        )
        conn.commit()
        self.auth._log_action(user['id'], 'create_report', f'Report: {title}')
        return cursor.lastrowid

    def execute_report(self, token: str, report_id: int) -> List[Dict]:
        """Execute a saved report by parsing its stored filter."""
        user = self.auth.get_user_from_token(token)
        if not user:
            raise PermissionError('Not authenticated')

        conn = get_connection()
        report = conn.execute(
            'SELECT * FROM reports WHERE id = ? AND creator_id = ?',
            (report_id, user['id'])
        ).fetchone()

        if not report:
            raise ValueError('Report not found')

        # Parse the stored filter and build query
        query, params = self._build_report_query(report['query_filter'])

        self.auth._log_action(user['id'], 'execute_report', f'Report ID: {report_id}')

        results = conn.execute(query, params).fetchall()
        return [dict(r) for r in results]

    def _build_report_query(self, stored_filter: str) -> Tuple[str, tuple]:
        """Build SQL query from a stored report filter.

        The filter was validated at creation time, but we re-validate
        and always use parameterized queries for defense-in-depth.
        """
        parts = stored_filter.split(':', 2)
        field, operator, value = parts

        # Re-validate field at execution time for defense-in-depth
        if field not in self.VALID_FIELDS:
            raise ValueError(f'Invalid field in stored filter: {field}')
        if operator not in self.VALID_OPERATORS:
            raise ValueError(f'Invalid operator in stored filter: {operator}')

        # Map operator to SQL - field comes from our validated set
        # so it's safe to interpolate directly
        op_map = {
            'eq': '=',
            'neq': '!=',
            'like': 'LIKE',
            'gt': '>',
            'lt': '<'
        }

        sql_op = op_map.get(operator, '=')

        if sql_op == 'LIKE':
            # For LIKE queries, wrap value in wildcards
            query = f"SELECT id, username, display_name, role FROM users WHERE {field} LIKE '%' || ? || '%'"
            return query, (value,)
        else:
            # Always use parameterized queries for values
            query = f"SELECT id, username, display_name, role FROM users WHERE {field} {sql_op} ?"
            return query, (value,)

    def list_reports(self, token: str) -> List[Dict]:
        """List all reports for the authenticated user."""
        user = self.auth.get_user_from_token(token)
        if not user:
            raise PermissionError('Not authenticated')

        conn = get_connection()
        reports = conn.execute(
            'SELECT id, title, query_filter, created_at FROM reports WHERE creator_id = ?',
            (user['id'],)
        ).fetchall()
        return [dict(r) for r in reports]


